  salvar: async ({ id }) => { const kv = {}; document.querySelectorAll('#ff [name]').forEach((e) => { const k = e.name, ty = CAMPOS.find((c) => c[0] === k)[2]; kv[k] = ['n'].includes(ty) || ['lat', 'lng', 'torres', 'unidadesTotal', 'vagas'].includes(k) ? (e.value === '' ? '' : num(e.value)) : e.value; }); const tip = $('#tip').value.split('\n').map((l) => l.split(';').map(num)).filter((a) => a[2] > 0).map(([dorm, area, preco]) => ({ dorm, area, preco })); kv.tipologias = tip.length ? tip : ''; const laz = $('#laz').value.split('\n').map((x) => x.trim()).filter(Boolean); kv.lazer = laz.length ? laz : ''; const p = db.projetos.find((x) => x.id === id), cur = V(p);
    for (const k of Object.keys(kv)) { if (k !== 'tipologias' && String(kv[k] ?? '') === String(cur[k] ?? '') ) delete kv[k]; else if (k === 'tipologias' && JSON.stringify(tip) === JSON.stringify(cur.tipologias || [])) delete kv[k]; else if (k === 'lazer' && JSON.stringify(laz) === JSON.stringify(cur.lazer || [])) delete kv[k]; }
    await setManual(id, kv); toast('Correções salvas (valores coletados preservados).'); ficha(id); },
