  $('#dlg').innerHTML = `<form method="dialog" style="float:right"><button>Fechar</button></form><h1>${esc(nome)}</h1><p class="muted">Posicionamento de marca · ${r.n} empreendimento(s) ${r.faixa ? '· ' + brl(r.faixa[0]) + (r.faixa[1] !== r.faixa[0] ? ' a ' + brl(r.faixa[1]) : '') : ''}</p>
  <h2>O que a base já mostra</h2><div class="card"><p class="small"><b>Diferenciais dos empreendimentos:</b> ${esc(r.diferenciais.join('; ') || 'sem dados')}</p><p class="small"><b>Áreas comuns mais frequentes:</b> ${esc(r.lazer.join(', ') || 'sem dados')}</p><p class="small"><b>Tipologias e bairros:</b> ${esc(r.dorms.join(', ') || 'n/d')} · ${esc(r.bairros.join(', ') || 'n/d')}</p><p class="small"><b>Público aparente (hipótese pelo ticket):</b> ${esc(r.publico || 'sem preço para inferir')}</p>
  <p class="small"><b>Sinais digitais coletados:</b> site oficial ${dg.siteOficial ? 'cadastrado' : 'não cadastrado'} · redes: ${esc(dg.redes.join(', ') || 'nenhuma encontrada nas páginas capturadas')} · ${dg.paginas} página(s) capturada(s) · vídeos: ${dg.videos} · imagem de compartilhamento: ${dg.og ? 'sim' : 'não'}</p>${dg.textos.length ? `<p class="small"><b>Textos de descrição das páginas:</b><br>${dg.textos.map((t) => '“' + esc(t) + '”').join('<br>')}</p>` : ''}</div>
  <h2>Sua avaliação</h2><div class="ff">${A2.MARCA_CRITERIOS.filter((c) => c.nota).map((c) => `<label>${esc(c.t)}${nota(c.k)}<span class="small muted">${esc(c.guia)}</span></label><label>Observações<input id="mk_${c.k}_obs" value="${esc(m[c.k + '_obs'] || '')}"></label>`).join('')}</div>
  ${A2.MARCA_CRITERIOS.filter((c) => !c.nota).map((c) => `<label class="small muted">${esc(c.t)} — ${esc(c.guia)}<textarea id="mk_${c.k}" rows="2">${esc(m[c.k] || '')}</textarea></label>`).join('')}
  <label class="small muted">Evidências (links, prints, datas)<textarea id="mk_evidencias" rows="2">${esc(m.evidencias || '')}</textarea></label><label class="small muted">Avaliador<input id="mk_avaliador" value="${esc(m.avaliador || '')}"></label>
  <div class="bar"><button class="pri" data-act="marcasalvar" data-id="${encodeURIComponent(nome)}">Salvar avaliação</button></div>${m.data ? `<p class="muted small">Última avaliação: ${fmtDT(m.data)}${m.avaliador ? ' por ' + esc(m.avaliador) : ''}</p>` : ''}`;
  $('#dlg').showModal(); if (RO) $('#dlg').querySelectorAll('input,select,textarea').forEach((x) => (x.disabled = true));
